from flask import Flask, request
import pymongo

app = Flask(__name__)
db = pymongo.MongoClient().cvedb

@app.post("/fetch_cve_data")
def fetch():
    values = request.values
    columns = {}
    for key, value in values.items():
        if key.startswith("columns[") and key.endswith("[data]"):
            columns[key.split("[")[1].split("]")[0]] = value
    sort = []
    for key, value in values.items():
        if key.startswith("order[") and key.endswith("[column]"):
            sort.append((columns[value], pymongo.ASCENDING))
    projection = {name: 1 for name in columns.values()}
    return {"data": list(db[values["retrieve"]].find({}, projection, sort=sort))}

from flask import Flask, request
import subprocess

app = Flask(__name__)

def build_cmd(img, out, password):
    script = f"expect -c 'spawn jpseek {img} {out}; expect \"Passphrase:\"; send \"{password}\\r\"; expect eof'"
