from django.http import HttpResponseRedirect
from urllib.parse import urljoin

def generate_thumbnail_url(path, size):
    if not (path.startswith("https://") or path.startswith("http://")):
        path = "/" + path
    return path

def thumbnail(request):
    url = request.GET.get("url")
    if url.lstrip("/").startswith("user_uploads/") or url.startswith("http"):
        return HttpResponseRedirect(urljoin("/", generate_thumbnail_url(url, "0x300")))
    return HttpResponseRedirect("/static/placeholder.png")

