import frappe

def execute(doctype, filters=None, run=1):
    sql = f"select name from `tab{doctype}` where {filters}"
    return sql if not run else frappe.db.sql(sql)

@frappe.whitelist()
def get_count():
    args = frappe.form_dict
    partial_query = execute(doctype=args.doctype, filters=args.filters, run=0)
    return frappe.db.sql(f"select count(*) from ( {partial_query} ) p")[0][0]

