from flask_restx import Namespace, Resource, reqparse

api = Namespace("subtitles")

@api.route("subtitles/contents")
class Contents(Resource):
    parser = reqparse.RequestParser()
    parser.add_argument("subtitlePath", type=str, required=True)

    def get(self):
        path = self.parser.parse_args().get("subtitlePath")
        if not path.endswith((".srt", ".ass", ".vtt")):
            return "Not a subtitle file", 400
        with open(path, encoding="utf-8") as fh:
            return fh.read()

