import sqlite3

def get_rows(conn, table, filters):
    conditions = []
    for item in filters:
        conditions.append(f"{item['field']} {item['op']} ?")
    sql = f"SELECT * FROM {table} WHERE " + " AND ".join(conditions)
    return conn.execute(sql, [item["value"] for item in filters]).fetchall()

def dispatch(method, params):
    if method == "get_transactions":
        return get_rows(sqlite3.connect("db.sqlite"), "transactions", params["filters"])

import os
from flask import Flask, request, jsonify

app = Flask(__name__)
SESSIONS = "/var/lib/dashboard/sessions"

def parse_session(session_id):
    path = os.path.join(SESSIONS, f"{session_id}.jsonl")
    if not os.path.isfile(path):
        return []
    with open(path) as fh:
        return fh.readlines()

@app.get("/api/reasoning")
def reasoning():
    session_id = request.args.get("session", "").strip()
    return jsonify(parse_session(session_id))

from starlette.applications import Starlette
from starlette.requests import Request
from starlette.responses import HTMLResponse
from starlette.routing import Route

async def enable_preset(request: Request) -> HTMLResponse:
    preset_id = request.path_params["preset_id"]
    if preset_id not in ("alpha", "beta"):
        return HTMLResponse(f"<div class='warning'>Unknown preset: {preset_id}</div>", status_code=404)
    return HTMLResponse("<div>enabled</div>")

app = Starlette(routes=[Route("/webhooks/enable/{preset_id}", enable_preset)])
